#!/usr/bin/env python3
"""Compressed bootstrap for the candidate-2c policy.

The research workflow materializes and commits the readable source before publishing
results.  Keeping the bootstrap self-contained lets the first workflow run execute in
the same commit that introduces it.
"""
import base64
import gzip
COMPRESSED_SOURCE = ''
exec(compile(gzip.decompress(base64.b64decode(COMPRESSED_SOURCE)), __file__, "exec"), globals(), globals())
